insert into public.supervisi_form (jenis, judul, pertanyaan)
select 'pra', 'Instrumen Umpan Balik Perencanaan Pembelajaran Mendalam', $j$[{"tipe": "bagian", "teks": "Petunjuk", "keterangan": "Berikan umpan balik terhadap perencanaan yang telah dipaparkan setiap kelompok dengan menggunakan instrumen berikut!\n\nSkala yang digunakan dalam menelaah:\n1 = hampir tidak ada\n2 = sedikit dan lemah\n3 = cukup\n4 = memadai", "id": "q1"}, {"tipe": "info", "teks": "Tautan Perencanaan Pembelajaran yang ditelaah", "id": "q2"}, {"tipe": "info", "teks": "Jenjang pada Perencanaan Pembelajaran", "id": "q3"}, {"tipe": "info", "teks": "Mata Pelajaran pada Perencanaan Pembelajaran", "id": "q4"}, {"tipe": "info", "teks": "Kelas pada Perencanaan Pembelajaran", "id": "q5"}, {"tipe": "info", "teks": "Judul Perencanaan Pembelajaran", "id": "q6"}, {"tipe": "bagian", "teks": "Keselarasan", "id": "q7"}, {"tipe": "skala", "teks": "Tujuan pembelajaran, langkah pembelajaran sudah mengarah pada pencapaian Dimensi Profil Lulusan", "opsi": ["1 — Hampir tidak ada", "2 — Sedikit dan lemah", "3 — Cukup", "4 — Memadai"], "komentar": "Komentar Kritis", "id": "q8"}, {"tipe": "skala", "teks": "Tujuan pembelajaran, langkah pembelajaran, dan asesmen pembelajaran sudah selaras", "opsi": ["1 — Hampir tidak ada", "2 — Sedikit dan lemah", "3 — Cukup", "4 — Memadai"], "komentar": "Komentar Kritis", "id": "q9"}, {"tipe": "bagian", "teks": "Kerangka Pembelajaran", "id": "q10"}, {"tipe": "skala", "teks": "Praktik pedagogis yang dituliskan sudah tergambar pada langkah pembelajaran dan/atau asesmen pembelajaran", "opsi": ["1 — Hampir tidak ada", "2 — Sedikit dan lemah", "3 — Cukup", "4 — Memadai"], "komentar": "Komentar Kritis", "id": "q11"}, {"tipe": "skala", "teks": "Lingkungan belajar yang dituliskan sudah tergambar pada langkah pembelajaran dan/atau asesmen pembelajaran", "opsi": ["1 — Hampir tidak ada", "2 — Sedikit dan lemah", "3 — Cukup", "4 — Memadai"], "komentar": "Komentar Kritis", "id": "q12"}, {"tipe": "skala", "teks": "Kemitraan pembelajaran yang dituliskan sudah tergambar pada langkah pembelajaran dan/atau asesmen pembelajaran", "opsi": ["1 — Hampir tidak ada", "2 — Sedikit dan lemah", "3 — Cukup", "4 — Memadai"], "komentar": "Komentar Kritis", "id": "q13"}, {"tipe": "skala", "teks": "Pemanfaatan digital yang dituliskan sudah tergambar pada langkah pembelajaran dan/atau asesmen pembelajaran", "opsi": ["1 — Hampir tidak ada", "2 — Sedikit dan lemah", "3 — Cukup", "4 — Memadai"], "komentar": "Komentar Kritis", "id": "q14"}, {"tipe": "bagian", "teks": "Langkah Pembelajaran", "id": "q15"}, {"tipe": "skala", "teks": "Langkah pembelajaran dapat memfasilitasi murid untuk merasakan pengalaman belajar MEMAHAMI (terlibat aktif mengonstruksi pengetahuan agar dapat memahami secara mendalam konsep atau materi dari berbagai sumber dan konteks).", "opsi": ["1 — Hampir tidak ada", "2 — Sedikit dan lemah", "3 — Cukup", "4 — Memadai"], "komentar": "Komentar Kritis", "id": "q16"}, {"tipe": "skala", "teks": "Langkah pembelajaran dapat memfasilitasi murid untuk merasakan pengalaman belajar MENGAPLIKASI (mengaplikasi pemahaman secara kontekstual dalam kehidupan nyata sebagai bagian dari pendalaman pengetahuan)", "opsi": ["1 — Hampir tidak ada", "2 — Sedikit dan lemah", "3 — Cukup", "4 — Memadai"], "komentar": "Komentar Kritis", "id": "q17"}, {"tipe": "skala", "teks": "Langkah pembelajaran dapat memfasilitasi murid untuk merasakan pengalaman belajar MEREFLEKSI (mengevaluasi dan memaknai proses serta hasil dari tindakan atau praktik nyata yang telah mereka lakukan dan menentukan tindaklanjut ke depan; serta mengelola proses belajarnya secara mandiri).", "opsi": ["1 — Hampir tidak ada", "2 — Sedikit dan lemah", "3 — Cukup", "4 — Memadai"], "komentar": "Komentar Kritis", "id": "q18"}, {"tipe": "skala", "teks": "Langkah perencanaan pembelajaran dapat memfasilitasi tindakan saling MEMULIAKAN antara Guru-Murid, Murid-Guru, Murid-Murid yang tercermin dalam bahasa verbal dan nonverbal", "opsi": ["1 — Hampir tidak ada", "2 — Sedikit dan lemah", "3 — Cukup", "4 — Memadai"], "komentar": "Komentar Kritis", "id": "q19"}, {"tipe": "skala", "teks": "Prinsip pembelajaran mendalam berupa berkesadaran, bermakna, dan/atau menggembirakan sudah tergambar pada setiap pengalaman belajar di langkah pembelajaran", "opsi": ["1 — Hampir tidak ada", "2 — Sedikit dan lemah", "3 — Cukup", "4 — Memadai"], "komentar": "Komentar Kritis", "id": "q20"}, {"tipe": "skala", "teks": "Perencanaan pembelajaran sudah mengakomodir pengalaman belajar yang sesuai dengan karakteristik peserta didik", "opsi": ["1 — Hampir tidak ada", "2 — Sedikit dan lemah", "3 — Cukup", "4 — Memadai"], "komentar": "Komentar Kritis", "id": "q21"}, {"tipe": "bagian", "teks": "Asesmen", "id": "q22"}, {"tipe": "skala", "teks": "Asesmen pada awal pembelajaran telah dilaksanakan untuk mendapatkan bukti kesiapan belajar secara emosional dan mental, pengetahuan awal, dan kebutuhan belajar murid", "opsi": ["1 — Hampir tidak ada", "2 — Sedikit dan lemah", "3 — Cukup", "4 — Memadai"], "komentar": "Komentar Kritis", "id": "q23"}, {"tipe": "skala", "teks": "Asesmen selama Proses Pembelajaran telah dilaksanakan sesuai perencanaan untuk memantau perkembangan belajar murid, memberikan umpan balik untuk perbaikan kontinyu (baik dari guru ke murid, maupun dari murid ke guru), melalui beragam teknik", "opsi": ["1 — Hampir tidak ada", "2 — Sedikit dan lemah", "3 — Cukup", "4 — Memadai"], "komentar": "Komentar Kritis", "id": "q24"}, {"tipe": "skala", "teks": "Asesmen hasil Pembelajaran direncanakan untuk mengukur pencapaian kompetensi sebagai bukti keberhasilan pembelajaran dengan beragam cara, antara lain: tes, portofolio, proyek, presentasi, dsb.", "opsi": ["1 — Hampir tidak ada", "2 — Sedikit dan lemah", "3 — Cukup", "4 — Memadai"], "komentar": "Komentar Kritis", "id": "q25"}, {"tipe": "bagian", "teks": "Kesimpulan", "id": "q26"}, {"tipe": "teks", "teks": "Tuliskan kelebihan Perencanaan Pembelajaran:", "id": "q27"}, {"tipe": "teks", "teks": "Tuliskan hal yang perlu ditingkatkan dari Perencanaan Pembelajaran:", "id": "q28"}, {"tipe": "teks", "teks": "Tuliskan rekomendasi dan lanjutkan dengan revisi Perencanaan Pembelajaran sesuai prinsip PM:", "id": "q29"}]$j$::jsonb
where not exists (select 1 from public.supervisi_form where judul = 'Instrumen Umpan Balik Perencanaan Pembelajaran Mendalam');

insert into public.supervisi_form (jenis, judul, pertanyaan)
select 'supervisi', 'Instrumen Implementasi dan Refleksi Perencanaan Pembelajaran', $j$[{"tipe": "bagian", "teks": "Petunjuk", "keterangan": "Berikan umpan balik terhadap praktik yang telah dilakukan dengan menggunakan instrumen berikut!", "id": "q1"}, {"tipe": "bagian", "teks": "Keselarasan", "id": "q2"}, {"tipe": "bukti_catatan", "teks": "Tindakan implementasi perencanaan selaras dengan perencanaan pembelajaran pada:\n(a) awal pembelajaran\n(b) inti pembelajaran dalam proses memahami, mengaplikasi, dan merefleksi\n(c) penutupan pembelajaran", "id": "q3"}, {"tipe": "bukti_catatan", "teks": "Upaya mencapai tujuan pembelajaran menuju pencapaian dimensi profil lulusan selaras dengan perencanaan pembelajaran", "id": "q4"}, {"tipe": "bagian", "teks": "Implementasi Kerangka Pembelajaran", "id": "q5"}, {"tipe": "bukti_catatan", "teks": "Praktik pedagogis yang diimplementasikan sudah tergambar pada langkah pembelajaran dan/atau asesmen pembelajaran", "id": "q6"}, {"tipe": "bukti_catatan", "teks": "Lingkungan belajar yang diimplementasikan sudah tergambar pada langkah pembelajaran dan/atau asesmen pembelajaran", "id": "q7"}, {"tipe": "bukti_catatan", "teks": "Kemitraan pembelajaran yang diimplementasikan sudah tergambar pada langkah pembelajaran dan/atau asesmen pembelajaran", "id": "q8"}, {"tipe": "bukti_catatan", "teks": "Pemanfaatan digital yang diimplementasikan sudah tergambar pada langkah pembelajaran dan/atau asesmen pembelajaran", "id": "q9"}, {"tipe": "bagian", "teks": "Langkah Pembelajaran", "id": "q10"}, {"tipe": "bukti_catatan", "teks": "Langkah pembelajaran yang dilakukan sesuai perencanaan dapat memfasilitasi tindakan saling MEMULIAKAN antara Guru-Murid, Murid-Guru, Murid-Murid yang tercermin dalam bahasa verbal dan nonverbal", "id": "q11"}, {"tipe": "bukti_catatan", "teks": "Langkah pembelajaran sudah memfasilitasi murid untuk merasakan pengalaman belajar MEMAHAMI (terlibat aktif mengonstruksi pengetahuan agar dapat memahami secara mendalam konsep atau materi dari berbagai sumber dan konteks).", "id": "q12"}, {"tipe": "bukti_catatan", "teks": "Langkah pembelajaran sudah memfasilitasi murid untuk merasakan pengalaman belajar MENGAPLIKASI (mengaplikasi pemahaman secara kontekstual dalam kehidupan nyata sebagai bagian dari pendalaman pengetahuan)", "id": "q13"}, {"tipe": "bukti_catatan", "teks": "Langkah pembelajaran sudah memfasilitasi murid untuk merasakan pengalaman belajar MEREFLEKSI (mengevaluasi dan memaknai proses serta hasil dari tindakan atau praktik nyata yang telah mereka lakukan dan menentukan tindaklanjut ke depan; serta mengelola proses belajarnya secara mandiri).", "id": "q14"}, {"tipe": "bukti_catatan", "teks": "Prinsip pembelajaran mendalam berupa berkesadaran, bermakna, dan/atau menggembirakan sudah tergambar pada setiap pengalaman belajar di langkah pembelajaran yang diimplementasikan.", "id": "q15"}, {"tipe": "bukti_catatan", "teks": "Praktik pembelajaran sudah mengakomodir pengalaman belajar yang sesuai dengan karakteristik murid (umur, tingkat perkembangan, kemampuan, bakat dan minat, gaya belajar, dll.)", "id": "q16"}, {"tipe": "bagian", "teks": "Asesmen", "id": "q17"}, {"tipe": "bukti_catatan", "teks": "Praktik Pembelajaran sudah melakukan asesmen untuk memberikan umpan balik guna memperbaiki proses pembelajaran.", "id": "q18"}, {"tipe": "bukti_catatan", "teks": "Praktik Pembelajaran sudah melakukan asesmen untuk mengukur ketercapaian tujuan pembelajaran sesuai karakteristik peserta didik", "id": "q19"}, {"tipe": "bukti_catatan", "teks": "Asesmen sudah dilakukan berdasarkan kriteria yang jelas dalam mengukur ketercapaian tujuan pembelajaran", "id": "q20"}, {"tipe": "bagian", "teks": "Refleksi", "id": "q21"}, {"tipe": "teks", "teks": "Pelajaran apa yang telah diperoleh dari Implementasi Perencanaan Pembelajaran yang telah dilakukan beserta faktor-faktor pendukungnya?", "id": "q22"}, {"tipe": "teks", "teks": "Hal-hal apa saja yang pencapaiannya belum memuaskan dari Implementasi Perencanaan Pembelajaran yang telah dilakukan beserta faktor-faktor penghambatnya?", "id": "q23"}, {"tipe": "teks", "teks": "Rencana tindak lanjut apa yang akan dibuat untuk perbaikan ke depan?", "id": "q24"}]$j$::jsonb
where not exists (select 1 from public.supervisi_form where judul = 'Instrumen Implementasi dan Refleksi Perencanaan Pembelajaran');
